#!/usr/bin/env python3
"""Generate the two Gaussian shaders from the original paired-tap kernel.

Native: sigma 16.5, 24 pairs. WASM: sigma 8, 8 pairs.
Only invariant arithmetic is moved offline; texture coordinates, clamping,
sampling order, chroma filtering, opacity and normalization are unchanged.
"""
from __future__ import annotations

import argparse
import math
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[1]
SHADERS = ROOT / "ui/shaders"
HEADER = """#version 440
// Generated by scripts/generate_gaussian_shaders.py. Do not edit constants.
#define GENYCASTER_WEBGL_KERNEL 0
layout(location = 0) in vec2 qt_TexCoord0;
layout(location = 0) out vec4 fragColor;
layout(std140, binding = 0) uniform buf {
    mat4 qt_Matrix;
    float qt_Opacity;
    vec2 sampleStep;
};
layout(binding = 1) uniform sampler2D source;
"""
CHROMA = """
// Reject weak visible chroma before the blur. Alpha-unpremultiplication of
// almost transparent text can otherwise create spurious colored edges.
vec4 chromaticSample(vec2 uv)
{
    vec4 pixel = texture(source, uv);
    float visibleChroma = max(pixel.r, max(pixel.g, pixel.b))
                        - min(pixel.r, min(pixel.g, pixel.b));
    return pixel * smoothstep(0.08, 0.22, visibleChroma);
}
"""


def kernel(pairs: int, denominator: float):
    weights = []
    total = 1.0
    for i in range(1, 2 * pairs, 2):
        first = math.exp(-(i * i) / denominator)
        second = math.exp(-((i + 1) ** 2) / denominator)
        weight = first + second
        weights.append((i + second / weight, weight))
        total += 2 * weight
    return weights, total


def literal(n: float) -> str:
    # More than the decimal precision needed to round a float32 correctly.
    return f"{n:.12f}"


def branch(pairs: int, denominator: float) -> str:
    weights, total = kernel(pairs, denominator)
    return "\n".join(
        [f"    accumulatePair(result, {literal(offset)}, {literal(weight)});"
         for offset, weight in weights]
        + [f"    fragColor = (result / {literal(total)}) * qt_Opacity;"]
    )


def shader(chromatic: bool) -> str:
    sample = "chromaticSample" if chromatic else "texture(source, "
    def at(uv: str) -> str:
        return f"{sample}({uv})" if chromatic else f"{sample}{uv})"

    return HEADER + (CHROMA if chromatic else "") + f"""
// The sample offsets and weights are immutable. Use straight-line calls
// rather than dynamically indexed arrays for GLSL ES 100 compatibility.
void accumulatePair(inout vec4 result, float distance, float weight)
{{
    vec2 offset = distance * sampleStep;
    result += {at('clamp(qt_TexCoord0 + offset, vec2(0.0), vec2(1.0))')} * weight;
    result += {at('clamp(qt_TexCoord0 - offset, vec2(0.0), vec2(1.0))')} * weight;
}}

void main()
{{
    vec4 result = {at('qt_TexCoord0')};
#if GENYCASTER_WEBGL_KERNEL
{branch(8, 128.0)}
#else
{branch(24, 544.5)}
#endif
}}
"""


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Check generated GLSL without writing")
    parser.add_argument("--qsb", type=Path, help="Rebuild native QSB with this Qt host compiler")
    args = parser.parse_args()
    if args.check and args.qsb:
        parser.error("--check cannot rebuild binaries")
    for name, chromatic in (("gaussian", False), ("reflection-gaussian", True)):
        path = SHADERS / (name + ".frag")
        source = shader(chromatic)
        if args.check:
            if path.read_text() != source:
                raise SystemExit(f"Generated shader is stale: {path}")
        else:
            path.write_text(source)
        if args.qsb:
            subprocess.run([str(args.qsb), "--glsl", "100es,120,150",
                            "--hlsl", "50", "--msl", "12",
                            "-o", str(path)+".qsb", str(path)], check=True)


if __name__ == "__main__":
    main()
